window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d351e8bc91e4a30d"]={"versions": [{"id": "FIG-d351e8bc91e4a30d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenformat-/Pufferlayout-Diagramm innerhalb der AUTOSAR Classic Platform (Diagnostic Services). Es spezifiziert die Byte-Reihenfolge und Segmentierung des Zielpuffers (<code>DestBuffer</code>), der über die C-API <code>Dem_DcmGetFreezeFrameDataByDTC</code> zwischen dem Diagnostic Event Manager (<code>Dem</code>) und dem Diagnostic Communication Manager (<code>Dcm</code>) übergeben wird, in Anlehnung an UDS (ISO 14229-1 Service 0x19 0x05 / 0x04) sowie OBD-II (ISO 15031-5 Service 0x02).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format definiert einen zusammenhängenden Datenstrom (<code>requested freeze frame record</code>) bestehend aus:</p>\n<ul class=\"fig-list\"><li><code>RecordNum</code> (Byte 0): Nummer des Freeze-Frame-Datensatzes (berechnet, z. B. 1, oder konfiguriert, z. B. erster Wert aus Liste).\n</li><li><code>Num of DIDs</code> (Byte 1): Anzahl der enthaltenen Data Identifier (<code>DTCSnapshotRecordNumberOfIdentifiers</code>).\n</li><li>Wiederkehrenden DID-Blöcken 1 bis N:\n<ul class=\"fig-list\"><li><code>1st DID</code> (Byte 2..3): 2-Byte Identifier des ersten Datenbezeichners.\n</li><li><code>Data #1</code> (Byte 4..j): Nutzdaten des ersten DID, aufgeschlüsselt in einzelne Datenelemente (<code>Data element #1</code> bis <code>Data element #N</code>).\n</li><li>Dazwischenliegende DIDs und Daten (<code>...</code>, Byte j..k).\n</li><li><code>Nth DID</code> (Byte k..(k+2)): 2-Byte Identifier des N-ten DID.\n</li><li><code>Data #N</code> (Byte (k+2)..n): Nutzdaten des N-ten DID.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei Aufruf von <code>Dem_DcmGetFreezeFrameDataByDTC</code> serialisiert das Dem-Modul den angeforderten Snapshot-Record in den bereitgestellten Puffer. Beginnend bei Offset 0 werden die Datensatznummer (<code>RecordNum</code>) und die Gesamtzahl der DIDs (<code>Num of DIDs</code>) geschrieben. Anschließend iteriert das Dem über alle zugeordneten DIDs und schreibt jeweils den 2-Byte DID gefolgt von dessen sequentiell zusammengesetzten Datenelementen in den Puffer, bis die Gesamtlänge n erreicht ist.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe gemäß <code>[SWS_Dem_00071]</code> für das Serialisierungsformat des Puffers <code>DestBuffer</code>. Entwickler müssen sicherstellen, dass der bereitgestellte Puffer mindestens n Bytes fasst. DIDs belegen stets 2 Bytes (Big-Endian gem. Standard). Bei Anforderung mit <code>RecordNumber = 0x00</code> greift <code>[SWS_Dem_00576]</code>, wodurch OBD-relevante Freeze Frames bereitgestellt werden, wobei die Datenfelder durch DID- statt PID-Werte eingeleitet werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3d6212f4d571770d", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenformat-/Pufferlayout-Diagramm innerhalb der AUTOSAR Classic Platform (Diagnostic Services). Es spezifiziert die Byte-Reihenfolge und Segmentierung des Zielpuffers (<code>DestBuffer</code>), der über die C-API <code>Dem_DcmGetFreezeFrameDataByDTC</code> zwischen dem Diagnostic Event Manager (<code>Dem</code>) und dem Diagnostic Communication Manager (<code>Dcm</code>) übergeben wird, in Anlehnung an UDS (ISO 14229-1 Service 0x19 0x05 / 0x04) sowie OBD-II (ISO 15031-5 Service 0x02).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format definiert einen zusammenhängenden Datenstrom (<code>requested freeze frame record</code>) bestehend aus:</p>\n<ul class=\"fig-list\"><li><code>RecordNum</code> (Byte 0): Nummer des Freeze-Frame-Datensatzes (berechnet, z. B. 1, oder konfiguriert, z. B. erster Wert aus Liste).\n</li><li><code>Num of DIDs</code> (Byte 1): Anzahl der enthaltenen Data Identifier (<code>DTCSnapshotRecordNumberOfIdentifiers</code>).\n</li><li>Wiederkehrenden DID-Blöcken 1 bis N:\n<ul class=\"fig-list\"><li><code>1st DID</code> (Byte 2..3): 2-Byte Identifier des ersten Datenbezeichners.\n</li><li><code>Data #1</code> (Byte 4..j): Nutzdaten des ersten DID, aufgeschlüsselt in einzelne Datenelemente (<code>Data element #1</code> bis <code>Data element #N</code>).\n</li><li>Dazwischenliegende DIDs und Daten (<code>...</code>, Byte j..k).\n</li><li><code>Nth DID</code> (Byte k..(k+2)): 2-Byte Identifier des N-ten DID.\n</li><li><code>Data #N</code> (Byte (k+2)..n): Nutzdaten des N-ten DID.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei Aufruf von <code>Dem_DcmGetFreezeFrameDataByDTC</code> serialisiert das Dem-Modul den angeforderten Snapshot-Record in den bereitgestellten Puffer. Beginnend bei Offset 0 werden die Datensatznummer (<code>RecordNum</code>) und die Gesamtzahl der DIDs (<code>Num of DIDs</code>) geschrieben. Anschließend iteriert das Dem über alle zugeordneten DIDs und schreibt jeweils den 2-Byte DID gefolgt von dessen sequentiell zusammengesetzten Datenelementen in den Puffer, bis die Gesamtlänge n erreicht ist.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe gemäß <code>[SWS_Dem_00071]</code> für das Serialisierungsformat des Puffers <code>DestBuffer</code>. Entwickler müssen sicherstellen, dass der bereitgestellte Puffer mindestens n Bytes fasst. DIDs belegen stets 2 Bytes (Big-Endian gem. Standard). Bei Anforderung mit <code>RecordNumber = 0x00</code> greift <code>[SWS_Dem_00576]</code>, wodurch OBD-relevante Freeze Frames bereitgestellt werden, wobei die Datenfelder durch DID- statt PID-Werte eingeleitet werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d351e8bc91e4a30d", "to": "FIG-3d6212f4d571770d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
